ALTER TABLE "User" ADD COLUMN "currency" TEXT NOT NULL DEFAULT 'EUR', ADD COLUMN "avatar" TEXT NOT NULL DEFAULT '';
ALTER TABLE "Wallet" ADD COLUMN "balanceCents" INTEGER NOT NULL DEFAULT 0, ALTER COLUMN "zeltokenBalance" SET DEFAULT 100;
ALTER TABLE "Listing" ADD COLUMN "priceCents" INTEGER NOT NULL DEFAULT 0, ADD COLUMN "category" TEXT NOT NULL DEFAULT 'autre', ADD COLUMN "images" TEXT[] NOT NULL DEFAULT ARRAY[]::TEXT[], ADD COLUMN "thumb" TEXT NOT NULL DEFAULT '', ALTER COLUMN "priceInZeltokens" SET DEFAULT 0;
UPDATE "Listing" SET "priceCents" = "priceInZeltokens" * 10;
ALTER TABLE "Order" ADD COLUMN "amountCents" INTEGER NOT NULL DEFAULT 0, ALTER COLUMN "amount" SET DEFAULT 0;
ALTER TABLE "Transaction" ADD COLUMN "amountCents" INTEGER NOT NULL DEFAULT 0, ALTER COLUMN "amount" SET DEFAULT 0;
CREATE INDEX "Listing_category_idx" ON "Listing"("category");
